//! Rendering: the project model and the SDK index in, every generated file
//! out. Pure (no file is read or written) and deterministic (no clocks, no
//! map-order dependence, no machine paths), so the output is the same on
//! every machine and golden-testable.

mod game;
pub mod lock;
mod root;

use std::collections::BTreeMap;

use crate::error::SyncError;
use crate::model::ProjectModel;
use crate::sdk::SdkIndex;

/// Project-relative path (forward slashes) → content.
pub type FileSet = BTreeMap<String, Vec<u8>>;

/// The engine crates the game crate's glue depends on (beyond plugin roots
/// and scripts crates), with the features it needs.
pub(crate) const GLUE_DEPENDENCIES: &[(&str, &[&str])] = &[
    ("pulsar_game", &[]),
    ("pulsar_pie_abi", &[]),
    ("tracing", &[]),
    // `main.rs`: `tracing_subscriber::fmt().with_env_filter(..)`.
    ("tracing-subscriber", &["env-filter", "fmt"]),
];

/// What the Rust generated for classes names, besides the glue's
/// (`pulsar_script_codegen::actor` and the `EngineClass` derive's output).
pub(crate) const CLASS_DEPENDENCIES: &[(&str, &[&str])] = &[
    ("engine_class_derive", &[]),
    ("inventory", &[]),
    ("pulsar_reflection", &[]),
    ("pulsar_scenedb", &[]),
    ("pulsar_script_vm", &[]),
    ("pulsar_world_registry", &[]),
    ("serde", &["derive"]),
    ("serde_json", &[]),
];

pub fn render(model: &ProjectModel, index: &SdkIndex) -> Result<FileSet, SyncError> {
    let root = root::RootManifest::new(model, index);
    let mut files = FileSet::new();
    files.insert(
        crate::paths::ROOT_MANIFEST.to_owned(),
        root.render().into_bytes(),
    );
    for (rel, content) in game::render(model, &root)? {
        files.insert(rel, content.into_bytes());
    }
    Ok(files)
}

/// The comment every generated Cargo file opens with.
pub(crate) const MANIFEST_HEADER: &str = "Generated by Pulsar from Pulsar.toml, the scripts crates and the engine SDK.\n\
Do not edit: every sync rewrites it. Enable plugins and name the project in\n\
Pulsar.toml; add dependencies to a scripts crate (engine crates with\n\
`{ workspace = true }`).";
